
import { MODELS } from './modelConfig';
import {
    createPanelCard,
    createPanelGroup,
    type PanelCard,
} from './ModelPanel.ts';

import type { ModelConfig } from './modelConfig';

// ------------------------------------------------------------
// Types
// ------------------------------------------------------------

interface PendingEmbed {
    model: ModelConfig;
    card: PanelCard;
}

// ------------------------------------------------------------
// Fullscreen elements
//
// Reuse existing elements when available. If the page doesn't
// include them, create them so embedded viewers can still load.
// ------------------------------------------------------------

function getOrCreateElement<T extends HTMLElement>(
    id: string,
    tag: string,
    parent: HTMLElement = document.body
): T {

    let element = document.getElementById(id) as T | null;

    if (element) {
        return element;
    }

    element = document.createElement(tag) as T;
    element.id = id;
    element.dataset.generated = 'true';

    parent.appendChild(element);

    return element;
}

function createFullscreenLayer() {

    const backdrop = getOrCreateElement<HTMLDivElement>(
        'fullscreen-backdrop',
        'div'
    );

    const controls = getOrCreateElement<HTMLDivElement>(
        'fullscreen-controls',
        'div'
    );

    const toggleBtn = getOrCreateElement<HTMLButtonElement>(
        'fs-toggle',
        'button',
        controls
    );

    const minimizeBtn = getOrCreateElement<HTMLButtonElement>(
        'fs-minimize',
        'button',
        controls
    );

    // Configure generated controls only.
    if (toggleBtn.dataset.generated === 'true') {
        toggleBtn.type = 'button';
        toggleBtn.textContent = 'Pause';
    }

    if (minimizeBtn.dataset.generated === 'true') {
        minimizeBtn.type = 'button';
        minimizeBtn.textContent = 'Minimize';
    }

    // Provide basic styling when the page doesn't already define
    // the fullscreen layer.
    if (backdrop.dataset.generated === 'true') {
        Object.assign(backdrop.style, {
            position: 'fixed',
            inset: '0',
            background: 'rgba(0, 0, 0, 0.85)',
            opacity: '0',
            visibility: 'hidden',
            zIndex: '999',
            transition: 'opacity 0.2s ease',
        });
    }

    if (controls.dataset.generated === 'true') {
        Object.assign(controls.style, {
            position: 'fixed',
            bottom: '20px',
            left: '50%',
            transform: 'translateX(-50%)',
            display: 'none',
            gap: '10px',
            zIndex: '1002',
        });
    }

    // Keep generated controls above the backdrop.
    if (toggleBtn.dataset.generated === 'true') {
        toggleBtn.style.pointerEvents = 'auto';
    }

    if (minimizeBtn.dataset.generated === 'true') {
        minimizeBtn.style.pointerEvents = 'auto';
    }

    return {
        backdrop,
        controls,
        toggleBtn,
        minimizeBtn,
    };
}

// ------------------------------------------------------------
// Initialize embedded models
// ------------------------------------------------------------

function initializeEmbeds(): void {

    const embeds = document.querySelectorAll<HTMLElement>(
        '.model-embed[data-model]'
    );

    if (embeds.length === 0) {
        return;
    }

    // Fullscreen controls are optional in the page HTML.
    const layer = createFullscreenLayer();

    const group = createPanelGroup(layer);

    // Models waiting to become visible.
    const pending = new Map<Element, PendingEmbed>();

    // --------------------------------------------------------
    // Lazy loading
    // --------------------------------------------------------

    const observer = new IntersectionObserver(
        (entries) => {

            for (const entry of entries) {

                if (!entry.isIntersecting) {
                    continue;
                }

                const item = pending.get(entry.target);

                if (!item) {
                    continue;
                }

                // Prevent duplicate initialization.
                pending.delete(entry.target);
                observer.unobserve(entry.target);

                try {

                    group.mount(item.model, item.card);

                } catch (error) {

                    item.card.statsEl.textContent =
                        'Failed to initialize viewer';

                    console.error(
                        `[model embeds] Failed to initialize "${item.model.name}":`,
                        error
                    );
                }
            }
        },
        {
            rootMargin: '200px',
        }
    );

    // --------------------------------------------------------
    // Prepare each embed
    // --------------------------------------------------------

    embeds.forEach((embed) => {

        const name = embed.dataset.model;

        if (!name) {
            return;
        }

        const model = MODELS.find(
            (candidate) => candidate.name === name
        );

        if (!model) {

            embed.textContent = `Unknown model "${name}".`;

            console.error(
                `[model embeds] No model named "${name}" in modelConfig.ts`
            );

            return;
        }

        // Create the same panel used by the dedicated model page.
        const card = createPanelCard(model, {
            showDescription: false,
        });

        // Add the card before observing or mounting it.
        embed.appendChild(card.section);

        pending.set(embed, {
            model,
            card,
        });

        observer.observe(embed);
    });

    // --------------------------------------------------------
    // Cleanup
    // --------------------------------------------------------

    window.addEventListener(
        'pagehide',
        () => {
            observer.disconnect();
            pending.clear();
            group.destroy();
        },
        { once: true }
    );
}

// ------------------------------------------------------------
// DOM readiness
// ------------------------------------------------------------

if (document.readyState === 'loading') {

    document.addEventListener(
        'DOMContentLoaded',
        initializeEmbeds,
        { once: true }
    );

} else {

    initializeEmbeds();
}
